 const voiceOptions=(id)=>['easy','straight','funny','carrie','minimal'].map(p=>`<option value="${p}" ${(state.voices[id]||'easy')===p?'selected':''}>${({easy:'Go easy on me',straight:'Tell me straight',funny:'Make me smile',carrie:'Fashion columnist',minimal:'Just the look'})[p]}</option>`).join('');
 function repeatLabel(h){if(h.days===0)return 'Worn today';if(h.last)return `Last worn ${h.last} · ${h.count} logged ${h.count===1?'wear':'wears'}`;if(h.similar)return `Same clothing logged ${h.similar} · accessories differ`;return 'No wears logged yet';}
