 function savedSurprise(){if(!state.surpriseOn||!state.surpriseIds?.length)return null;return {looks:state.surpriseIds.map(lookById).filter(Boolean),trace:[{node:'surprise',builder:'stylepro-outfit-builder'}],builder:'stylepro-outfit-builder',context:''};}
