 function startCarousel(){
  const root=$('.sp-carousel');if(!root)return;stopCarousel();const slides=[...root.querySelectorAll('.sp-carousel-slide')],track=root.querySelector('.sp-carousel-track');if(slides.length<2)return;
  let index=0,paused=true,hover=false,focused=false,touch=null;
  const pauseButton=root.querySelector('[data-carousel-pause]');
  function pauseLabel(){pauseButton.textContent=paused?'Play ▷':'Pause Ⅱ';pauseButton.setAttribute('aria-label',paused?'Play carousel':'Pause carousel');}
  function go(next){index=(next+slides.length)%slides.length;track.style.transform=`translateX(-${index*100}%)`;slides.forEach((slide,i)=>{slide.inert=i!==index;slide.setAttribute('aria-hidden',String(i!==index));});root.querySelectorAll('.sp-carousel-dots [data-carousel-go]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.carouselGo)===index)));root.querySelector('.sp-carousel-count').textContent=String(index+1).padStart(2,'0')+' / '+String(slides.length).padStart(2,'0');fit();}
  function fit(){root.querySelector('.sp-carousel-window').style.height=slides[index].offsetHeight+'px';}const observer=new ResizeObserver(fit);slides.forEach(s=>observer.observe(s));
  function navigate(next){paused=true;pauseLabel();go(next);}
  root.querySelectorAll('[data-carousel-go]').forEach(b=>b.onclick=()=>navigate(Number(b.dataset.carouselGo)));root.querySelector('[data-carousel-prev]').onclick=()=>navigate(index-1);root.querySelector('[data-carousel-next]').onclick=()=>navigate(index+1);pauseButton.onclick=()=>{paused=!paused;pauseLabel();};
  root.onmouseenter=()=>hover=true;root.onmouseleave=()=>hover=false;root.onfocusin=()=>focused=true;root.onfocusout=ev=>focused=root.contains(ev.relatedTarget);
  root.onpointerdown=ev=>{if(ev.pointerType==='touch')touch={x:ev.clientX,y:ev.clientY};};root.onpointerup=ev=>{if(!touch)return;const dx=ev.clientX-touch.x,dy=ev.clientY-touch.y;touch=null;if(Math.abs(dx)>45&&Math.abs(dy)<70){paused=true;pauseLabel();window.StyleProPhone?.haptic('swipe');go(index+(dx<0?1:-1));}};root.onpointercancel=()=>touch=null;
  const timer=setInterval(()=>{if(!paused&&!hover&&!focused&&!document.hidden&&view==='today')go(index+1);},6000);stopCarousel=()=>{clearInterval(timer);observer.disconnect();};pauseLabel();go(0);
 }
