  const related=run('',200,{avoidRepeats:state.avoid}).looks.filter(l=>C.signature(l.pieces)!==C.signature(look.pieces)).map(l=>({look:l,shared:l.pieces.filter(pid=>matchedIds.has(pid)&&['top','bottom','dress','layer'].includes(C.role(itemById(pid))))})).filter(x=>x.shared.length).sort((a,b)=>b.shared.length-a.shared.length||a.look.id.localeCompare(b.look.id)).slice(0,3);
  modal(`<div class="sp-inspired-panel"><button class="sp-inspired-close" data-sp-close aria-label="Close wardrobe match">×</button><p class="sp-kicker">THE INSPIRATION EDIT</p><h2 id="sp-dialog-title">Love the look.<br><em>Start with your wardrobe.</em></h2><div class="sp-inspired-intro"><div class="sp-inspired-source" aria-hidden="true">${outfitCollage(look)}</div><div><h3>${e(look.title)}</h3><p>${different?'Other pieces that could echo this look.':'Let’s see what is already in your closet.'}</p><div class="sp-match-stats">${exact?'<span><b>'+exact+'</b> already yours</span>':''}${similar?'<span><b>'+similar+'</b> similar details</span>':''}${near?'<span><b>'+near+'</b> possible alternatives</span>':''}${missing?'<span><b>'+missing+'</b> no close match recorded</span>':''}</div><p class="sp-note">${different?'Original pieces are excluded from this comparison.':'This look comes from your current lookbook. Your original pieces can appear as exact matches.'}</p></div></div><div class="sp-match-modes" role="group" aria-label="Compare wardrobe pieces"><button class="sp-btn ${!different?'primary':''}" data-sp-match-mode="exact" aria-pressed="${!different}">What I already have</button><button class="sp-btn ${different?'primary':''}" data-sp-match-mode="different" aria-pressed="${different}">Try other pieces</button></div><div class="sp-match-list">${rows.map(({reference,match})=>{const own=match&&itemById(match.itemId);return `<article class="sp-match-row"><div class="sp-match-request"><small>IN THE LOOK</small><h4>${e(reference.name)}</h4></div><div class="sp-match-result ${match?'':'missing'}">${own?'<button class="sp-match-thumb" data-piece="'+e(own.id)+'" aria-label="Inspect '+e(own.name)+'">'+cutoutVisual(own)+'</button>':'<span class="sp-match-empty" aria-hidden="true">✧</span>'}<div><span class="sp-match-status">${match?({exact:'Already yours',similar:'Similar recorded details',near:'Possible alternative'}[match.kind]):'No close match recorded'}</span><h4>${own?e(own.name):'A detail to check in your closet'}</h4>${match?.shared.length?'<p>In common: '+e(match.shared.join(' · '))+'</p>':''}${match?.differences.length?'<p class="sp-match-differences">'+e(match.differences.join('; '))+'.</p>':''}${own?'<button class="sp-match-link" data-sp-anchor-piece="'+e(own.id)+'">See looks with this piece ↗</button>':'<p>It may be uncataloged. Check before looking for a swap.</p>'}</div></div></article>`;}).join('')}</div><p class="sp-note">Compared using recorded garment names and categories. Similarity does not confirm fit, fabric, condition or suitability for every occasion. ${refs.some(i=>C.role(i)==='shoe')?'':'This source look has no confirmed shoe item attached.'}</p>${related.length?'<div class="sp-inspired-related"><h3>More ways to wear your pieces</h3><div>'+related.map(x=>'<button data-sp-inspired-look="'+e(x.look.id)+'"><span class="sp-related-art">'+outfitCollage(x.look)+'</span><strong>'+e(x.look.title)+'</strong><small>'+x.shared.length+' clothing '+(x.shared.length===1?'piece':'pieces')+' in common ↗</small></button>').join('')+'</div></div>':''}<p class="sp-inspired-private">Saved to My inspirations in this browser. ${Object.keys(state.inspired).length} different ${Object.keys(state.inspired).length===1?'look':'looks'} explored. No community totals are shown.</p><button class="sp-btn" data-sp-close>Back to my lookbook</button></div>`);
  dialog.querySelectorAll('[data-sp-match-mode]').forEach(b=>b.onclick=()=>openInspired(id,b.dataset.spMatchMode==='different'));
  dialog.querySelectorAll('[data-sp-inspired-look]').forEach(b=>b.onclick=()=>{dialog.close();openLook(b.dataset.spInspiredLook);});
  dialog.querySelectorAll('[data-piece]').forEach(b=>b.addEventListener('click',()=>dialog.close()));
