 function planDialog(id,date){modal(`<h2 id="sp-dialog-title">Give this look a plan.</h2><form id="sp-plan-form"><label class="sp-field">What’s happening?<input name="title" required maxlength="140" value="${e(state.q)}" placeholder="Dinner, meeting, filming…"></label><label class="sp-field">Date<input name="date" type="date" required value="${date||localDate()}"></label><label class="sp-field">Outfit<select name="look">${wardrobe.looks.filter(l=>!l.neural&&l.pieces.every(i=>C.owned(itemById(i)))).map(l=>`<option value="${l.id}" ${l.id===id?'selected':''}>${e(l.title)}</option>`).join('')}</select></label><p class="sp-note">Saved in your Style Pro planner on this browser. No external calendar event will be created.</p><div class="sp-actions"><button class="sp-btn primary">Save my plan</button><button type="button" class="sp-btn" data-sp-close>Cancel</button></div></form>`);$('#sp-plan-form').onsubmit=ev=>{ev.preventDefault();const fd=new FormData(ev.target);window.wardrobeStylist.plan(fd.get('date'),fd.get('title').trim(),fd.get('look'));dialog.close();if(view==='today')renderToday();toast('Your look is planned.');};}
