 function exportDiary(){const lines=['# Trish — Style Pro real-life diary','',`Exported ${localDate()}`,'','Only user-confirmed wears count. Photos, plans and saved looks are not proof of wear.','',`Catalog: ${wardrobe.items.length} records. Curated recipes: ${wardrobe.looks.filter(l=>!l.neural).length}.`,`Different logged outfits: ${new Set(state.wears.map(w=>w.signature)).size}.`,'','## Worn looks','',...state.wears.map(w=>`- ${w.date} | ${lookById(w.lookId)?.title||w.lookId} | ${w.event||'No event recorded'} | ${w.outcome||'Outcome pending'}\n  Pieces: ${w.itemIds.map(id=>itemById(id)?.name||id).join('; ')}\n  Footwear note: ${w.shoeNote||'See catalog shoe record'}`),'','## Feedback','',...Object.entries(state.feedback).map(([id,f])=>`- ${lookById(id)?.title||id}: ${f.reason}${f.note?' — '+f.note:''}`),'','## Planned, not yet confirmed worn','',...plans().map(p=>`- ${p.date}: ${p.title} — ${lookById(p.lookId)?.title||p.lookId}`),'','## What this can establish','','Whether useful outfits were worn, varied and enjoyed. It cannot establish time saved or market demand without user feedback and further observation.','', '## Backup data','', '```json',JSON.stringify({stylePro:state,stylistProfile:window.styleProStylist?.preferences(),vault:window.styleProMVP?.getBackup(),pins:saved,planner:window.wardrobeStylist.events,doll:localStorage.getItem('trish-doll-v1')},null,2),'```'];const a=document.createElement('a');const url=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/markdown'}));a.href=url;a.download='Style-Pro-Trish-Diary-'+localDate()+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your diary and backup are exported.');}
