 window.stylePro={noteFeedback(id,note){if(!lookById(id))return;state.feedback[id]={value:'pass',reason:'Stylist conversation',note:String(note).slice(0,1200),date:localDate()};persist();renderActive();},refresh:renderActive,getDailyPipeline:()=>dailyPipeline,openEventPlan:date=>planDialog(run('',1).looks[0]?.id,date),styleForEvent:q=>run(q,6).looks,calendarShortlist:(q,date)=>run(q,3,{date}).looks,repeatForLook:(l,date)=>repeatLabel(C.history(l,wardrobe.items,state.wears,date||localDate())),getState:()=>JSON.parse(JSON.stringify(state)),logChosen,undoWear,run};
 function closetGroup(item){
 const cat=(item.category||'').toLowerCase();
 const name=(item.name||'').toLowerCase();
 if(cat==='shoes') return 'Shoes';
 if(cat==='jewelry') return 'Jewelry';
 if(cat==='handbags') return 'Bags';
 if((cat==='accessories'||cat==='scarves')&&/\bscarf\b/.test(name)&&!/scarf-print|scarf-handle/.test(name)) return 'Scarves';
 if(cat==='accessories') return 'Accessories';
 return 'Clothes';
}
function groupCloset(){
 const grid=document.getElementById('catalog-grid');
 if(!grid||document.body.dataset.spView!=='collection') return;
 const cards=[...grid.querySelectorAll('.piece-card')];
 if(!cards.length||grid.querySelector('.sp-closet-group')) return;
 const order=['Clothes','Shoes','Jewelry','Scarves','Bags','Accessories'];
 const buckets=Object.fromEntries(order.map(name=>[name,[]]));
 cards.forEach(card=>{const id=card.querySelector('[data-piece]')?.dataset.piece; const item=typeof itemById==='function'?itemById(id):null; const name=item?closetGroup(item):'Clothes'; (buckets[name]||buckets.Clothes).push(card);});
 grid.textContent='';
 grid.classList.add('sp-closet-groups');
 order.forEach(name=>{if(!buckets[name].length) return; const section=document.createElement('section'); section.className='sp-closet-group'; section.innerHTML=`<h2>${name}</h2><div class="sp-closet-grid"></div>`; const inner=section.querySelector('.sp-closet-grid'); buckets[name].forEach(card=>inner.append(card)); grid.append(section);});
}
if(typeof renderCatalog==='function'&&!renderCatalog._closetGroups){
 const oldCatalog=renderCatalog;
 renderCatalog=function(){const out=oldCatalog.apply(this,arguments); groupCloset(); return out;};
 renderCatalog._closetGroups=true;
}
